New-Item -ItemType Directory -Path $base -Force | Out-Null
foreach ($name in $sets.Keys) {
  $dir = Join-Path $base $name
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
  $set = $sets[$name]
  for ($i = 0; $i -lt $set.Urls.Count; $i++) {
    $n = $set.Start + $i
    $file = Join-Path $dir "$n.jpg"
    if (Test-Path $file) { continue }
    & curl.exe -L --fail --silent --show-error --retry 2 --output $file $set.Urls[$i]
    if ($LASTEXITCODE -ne 0) { Remove-Item $file -Force -ErrorAction SilentlyContinue; throw "Download failed: $name/$n.jpg" }
  }
  $valid = @(Get-ChildItem $dir -Filter '*.jpg' -File | Where-Object Length -gt 5KB)
  $bad = @(Get-ChildItem $dir -Filter '*.jpg' -File | Where-Object Length -le 5KB)
  [pscustomobject]@{ Category=$name; Count=$valid.Count; SmallOrInvalid=$bad.Count }
}
